// перебор: каждый круг проверяет каждую точку — O(n·q)
public int[] CountPoints(int[][] points, int[][] queries) {
    var answer = new int[queries.Length];
    for (int j = 0; j < queries.Length; j++) {
        int x = queries[j][0], y = queries[j][1], r = queries[j][2];
        foreach (var p in points) {
            int dx = p[0] - x, dy = p[1] - y;
            if (dx * dx + dy * dy <= r * r) answer[j]++;   // ≤: точка на окружности — внутри
        }
    }
    return answer;
}

