public int[] CountPoints(int[][] points, int[][] queries) {
    int size = 1;
    foreach (var q in queries) size = Math.Max(size, q[2]);         // клетка не меньше любого r
    var grid = new Dictionary<long, List<int>>();
    for (int i = 0; i < points.Length; i++) {
        long key = Key(points[i][0] / size, points[i][1] / size);    // здесь x, y ≥ 0; в мире — FloorToInt
        if (!grid.TryGetValue(key, out var bucket)) grid[key] = bucket = new List<int>();
        bucket.Add(i);
    }
    var answer = new int[queries.Length];
    for (int j = 0; j < queries.Length; j++) {
        int x = queries[j][0], y = queries[j][1], r = queries[j][2], cx = x / size, cy = y / size;
        for (int gy = cy - 1; gy <= cy + 1; gy++)
            for (int gx = cx - 1; gx <= cx + 1; gx++) {
                if (!grid.TryGetValue(Key(gx, gy), out var bucket)) continue;  // пустая клетка — один поиск
                foreach (int i in bucket) {
                    int dx = points[i][0] - x, dy = points[i][1] - y;
                    if (dx * dx + dy * dy <= r * r) answer[j]++;
                }
            }
    }
    return answer;
}

static long Key(int cx, int cy) => ((long)cx << 32) | (uint)cy;    // cx — старшая половина, cy — младшая

