int Nearest(float px, float py, int[] best, float[] bestD, int maxRing) {
    int k = best.Length, count = 0;
    int cx = Mathf.FloorToInt(px / size), cy = Mathf.FloorToInt(py / size);
    for (int ring = 0; ring <= maxRing; ring++) {
        for (int gy = cy - ring; gy <= cy + ring; gy++)
            for (int gx = cx - ring; gx <= cx + ring; gx++) {
                if (Math.Max(Math.Abs(gx - cx), Math.Abs(gy - cy)) != ring) continue;  // только край кольца
                if (!grid.TryGetValue(Key(gx, gy), out var bucket)) continue;
                foreach (int i in bucket) {
                    float dx = xs[i] - px, dy = ys[i] - py, d = dx * dx + dy * dy;
                    if (count == k && d >= bestD[k - 1]) continue;       // не лучше худшего из k
                    int j = count < k ? count++ : k - 1;
                    while (j > 0 && bestD[j - 1] > d) { best[j] = best[j - 1]; bestD[j] = bestD[j - 1]; j--; }
                    best[j] = i; bestD[j] = d;
                }
            }
        float edge = ring * size;                       // всё за кольцом — не ближе edge
        if (count == k && bestD[k - 1] <= edge * edge) break;
    }
    return count;
}

