// квадродерево: запрос спускается только в узлы, которые задевает круг
void Query(QuadNode node, Vector2 p, float r, List<int> result) {
    if (!Intersects(node.Bounds, p, r)) return;            // узел мимо — всё поддерево отсечено
    if (node.Kids == null) {                               // лист: проверяем его объекты
        foreach (int id in node.Items)
            if ((pos[id] - p).sqrMagnitude <= r * r) result.Add(id);
        return;
    }
    foreach (var kid in node.Kids) Query(kid, p, r, result);
}

static bool Intersects(Rect b, Vector2 p, float r) {       // ближайшая к центру точка прямоугольника
    float dx = p.x - Mathf.Clamp(p.x, b.xMin, b.xMax), dy = p.y - Mathf.Clamp(p.y, b.yMin, b.yMax);
    return dx * dx + dy * dy <= r * r;
}

