[BurstCompile]
struct FillGridJob : IJobParallelFor {
    [ReadOnly] public NativeArray<float2> pos;
    public NativeParallelMultiHashMap<int, int>.ParallelWriter grid;
    public float size;
    public int width;                                   // клеток по x
    public void Execute(int i) {
        int2 c = (int2)math.floor(pos[i] / size);
        grid.Add(c.x + c.y * width, i);                 // клетка → агент
    }
}

int CountInCell(NativeParallelMultiHashMap<int, int> map, int key) {   // обход корзины
    int count = 0;
    if (map.TryGetFirstValue(key, out int agent, out var it))
        do count++; while (map.TryGetNextValue(out agent, ref it));
    return count;
}
